import { useSession } from 'next-auth/react';
import { fetchUserProfileApi } from '@/services/api/userService';
import { UserProfile } from '@/lib/models';

/**
 * Custom hook for fetching and managing user profile data
 * Handles session-dependent queries with proper caching and retry logic
 */
export function useUserProfile(): UseQueryResult<UserProfile | null> {
  const { data: session, status } = useSession();
  const userId = session?.user?.id;
  const token = session?.user?.accessToken;

  console.log('[useUserProfile] Hook called:', {
    userId,
    hasToken: !!token,
    sessionStatus: status,
  });

  const query = useQuery({
    queryKey: ['user', 'profile', userId],
    queryFn: async () => {
      console.log('[useUserProfile] queryFn executing:', { userId, tokenLength: token?.length });

      if (!userId || !token) {
        console.warn('[useUserProfile] Missing userId or token, returning null');
        return null;
      }

      try {
        const result = await fetchUserProfileApi(userId, token);
        console.log('[useUserProfile] Query successful:', {
          hasResult: !!result,
          userId: result?.id,
          email: result?.email,
          role: result?.role,
        });
        return result;
      } catch (error) {
        console.error('[useUserProfile] Query failed:', {
          error: error instanceof Error ? error.message : String(error),
          userId,
        });
        throw error;
      }
    },
    // Only fetch when we have both userId and token
    enabled: !!userId && !!token && status === 'authenticated',
    // Cache user profile for 5 minutes
    staleTime: 5 * 60 * 1000,
    // Keep data in cache for 10 minutes
    gcTime: 10 * 60 * 1000,
    // Retry failed requests with exponential backoff
    retry: (failureCount) => {
      console.log('[useUserProfile] Retry attempt:', failureCount);
      return failureCount < 3;
    },
    retryDelay: (attemptIndex) => Math.min(1000 * 2 ** attemptIndex, 30000),
  });

  return query;
}

/**
 * Hook for refetching user profile on demand
 */
export function useRefreshUserProfile() {
  const { data: session } = useSession();
  const userId = session?.user?.id;
  const token = session?.user?.accessToken;

  return async () => {
    console.log('[useRefreshUserProfile] Manual refresh triggered for:', userId);

    if (!userId || !token) {
      console.warn('[useRefreshUserProfile] Cannot refresh without userId or token');
      return null;
    }

    try {
      const result = await fetchUserProfileApi(userId, token);
      console.log('[useRefreshUserProfile] Refresh successful');
      return result;
    } catch (error) {
      console.error('[useRefreshUserProfile] Refresh failed:', error);
      throw error;
    }
  };
}
"}

